(2, 'Desarrollo Pagina Web ', 'Este proyecto fue más sencillo. Consistía en desarrollar nuestras propias páginas web para cualquier cosa. Podía ser para vender productos o para mostrar algún tipo de información sobre algo.', );
INSERT INTO `proyectos` (`IdProyecto`, `Nombre`, `Descripcion`, `foto`) VALUES
(3, 'Desarrollo y administración de base de datos', 'En este proyecto nuestro objetivo era desarrollar una base de datos para una empresa, y administrarla. Para ello nos tuvimos que inventar una empresa, de fabricación o ventas de algún producto, y crear cuál sería su base de datos. Después añadir algunos datos sobre productos y administrarla.', );

